std::vector<std::pair<std::string, std::string>> parseConsensus(const std::string& consensus) {
    std::vector<std::pair<std::string, std::string>> relays;
    std::istringstream iss(consensus);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.find("r ") == 0) {
