                                     WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                     WINHTTP_NO_PROXY_NAME, 
                                     WINHTTP_NO_PROXY_BYPASS, 0);

    if (hSession) {
        HINTERNET hConnect = WinHttpConnect(hSession, L"descriptor.torproject.org", INTERNET_DEFAULT_HTTP_PORT, 0);
        if (hConnect) {
            HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", L"/descriptor/" + hiddenService, NULL, WINHTTP_NO_REFERER, 
                                                    WINHTTP_DEFAULT_ACCEPT_TYPES, 0);
            if (hRequest) {
                BOOL bResults = WinHttpSendRequest(hRequest, 
                                                   WINHTTP_NO_ADDITIONAL_HEADERS, 0, 
                                                   WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
                if (bResults) {
                    bResults = WinHttpReceiveResponse(hRequest, NULL);
                    if (bResults) {
                        DWORD dwSize = 0;
                        DWORD dwDownloaded = 0;
                        LPSTR pszOutBuffer;
                        std::string descriptor;

                        do {
                            dwSize = 0;
                            if (!WinHttpQueryDataAvailable(hRequest, &dwSize)) {
                                break;
                            }

                            pszOutBuffer = new char[dwSize + 1];
                            if (!pszOutBuffer) {
                                break;
                            }

                            ZeroMemory(pszOutBuffer, dwSize + 1);

                            if (!WinHttpReadData(hRequest, (LPVOID)pszOutBuffer, dwSize, &dwDownloaded)) {
                                delete[] pszOutBuffer;
                                break;
                            }

                            descriptor += pszOutBuffer;
                            delete[] pszOutBuffer;
                        } while (dwSize > 0);

                        return descriptor;
                    }
                }
                WinHttpCloseHandle(hRequest);
            }
            WinHttpCloseHandle(hConnect);
        }
        WinHttpCloseHandle(hSession);
    }
    return "";
}

// Parse the hidden service descriptor
std::vector<std::string> parseDescriptor(const std::string& descriptor) {
    std::vector<std::string> introductionPoints;
    std::istringstream iss(descriptor);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.find("introduction-point ") == 0) {
            introductionPoints.push_back(line.substr(18));
        }
    }
    return introductionPoints;
}

// Verify the hidden service descriptor signature
bool verifyDescriptorSignature(const std::string& descriptor, const std::string& public_key_pem) {
    BIO* bio = BIO_new_mem_buf((void*)public_key_pem.c_str(), -1);
    EVP_PKEY* public_key = PEM_read_bio_PUBKEY(bio, NULL, NULL, NULL);
    BIO_free(bio);

    if (!public_key) {
        std::cerr << "Failed to load public key.\n";
        return false;
    }

    std::string signature;
    std::istringstream iss(descriptor);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.find("signature ") == 0) {
            signature = line.substr(10);
            break;
        }
    }

    if (signature.empty()) {
        std::cerr << "No signature found in descriptor.\n";
        EVP_PKEY_free(public_key);
        return false;
    }

    std::string message = descriptor.substr(0, descriptor.find("signature "));

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        std::cerr << "Failed to create EVP_MD_CTX.\n";
        EVP_PKEY_free(public_key);
        return false;
    }

    if (EVP_VerifyInit_ex(ctx, EVP_sha256(), NULL) != 1) {
        std::cerr << "Failed to initialize verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        return false;
    }

    if (EVP_VerifyUpdate(ctx, message.c_str(), message.size()) != 1) {
        std::cerr << "Failed to update verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        return false;
    }

    unsigned char* sig = (unsigned char*)signature.c_str();
    int result = EVP_VerifyFinal(ctx, sig, signature.size(), public_key);

    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(public_key);

    if (result == 1) {
        std::cout << "Descriptor signature verified successfully.\n";
        return true;
    } else {
        std::cerr << "Descriptor signature verification failed.\n";
        return false;
    }
}

